import pytest
import time
from datetime import datetime, timedelta
from cachetools.func import (
    fifo_cache,
    lfu_cache,
    lru_cache,
    rr_cache,
    ttl_cache,
)


def test_fifo_cache_default_maxsize():
    f = fifo_cache()(lambda x: x * 2)
    assert f.cache_parameters() == {"maxsize": 128, "typed": False}
    data = list(range(150))
    for i in data:
        f(i)
    info = f.cache_info()
    assert info.currsize <= 128
    f.cache_clear()


def test_lfu_cache_default_maxsize():
